import { JxButton, JxInputField, JxSelect, JxSwitch, JxToast } from '@jinx-ui/react';

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор', meta: 'может менять задачи' },
  { value: 'admin', label: 'Администратор', meta: 'полный доступ' },
];

const EMAIL_PATTERN = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [invited, setInvited] = useState<string | null>(null);

  const isValidEmail = EMAIL_PATTERN.test(email.trim());
  const errorText = touched && !isValidEmail ? 'Введите адрес вида name@company.com' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!isValidEmail) {
      setTouched(true);
      return;
    }
    setInvited(email.trim());
    setEmail('');
    setTouched(false);
  };

  return (
    <div style={{ display: 'grid', gap: 16, maxWidth: 420 }}>
      {invited && (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`${invited} получит доступ${notify ? ' и письмо со ссылкой' : ''}`}
          onClose={() => setInvited(null)}
        />
      )}

      <form onSubmit={submit} style={{ display: 'grid', gap: 16 }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          name="email"
          required
          autoComplete="email"
          placeholder="name@company.com"
          helperText="Приглашение действует 7 дней"
          value={email}
          errorText={errorText}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
        />

        <JxSelect
          label="Роль"
          options={ROLES}
          value={role}
          onValueChange={setRole}
          placeholder="Выберите роль"
        />

        <JxSwitch
          label="Отправить уведомление на почту"
          name="notify"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <div style={{ display: 'flex', gap: 8 }}>
          <JxButton type="submit" variant="primary" disabled={!isValidEmail}>
            Отправить приглашение
          </JxButton>
        </div>
      </form>
    </div>
  );
}

